insert into public.tipos_laudo (id, codigo, nome, descricao, ordem, ativo) values
  ('523a396e-5be1-5740-9dee-bb11a9615db4', 'tecnologias_saude', 'Tecnologias em Saúde (fornecimento e cobertura)', 'Avaliação médico-pericial de demandas de fornecimento/cobertura de tecnologias em saúde (medicamentos, procedimentos, tratamentos continuados, terapias, órteses, próteses, OPME, dispositivos, equipamentos de uso domiciliar, home care e exames), separando comprovação diagnóstica, gravidade, indicação assistencial, caracterização regulatória, evidência científica, PCDT/CONITEC/SUS, NATJUS, alternativas, adequação individual, necessidade/imprescindibilidade e risco da demora.', 5, true);
